:root {
  --hr-primary: #904d00;
  --hr-primary-soft: #ffa04b;
  --hr-primary-dark: #6f3900;
  --hr-background: #f8f9ff;
  --hr-surface: #ffffff;
  --hr-text: #121c2a;
  --hr-muted: #5f6977;
  --hr-border: #ead9c9;
  --hr-soft-surface: #fff7ef;
}

/* Global page styling */
body {
  background-color: var(--hr-background);
  color: var(--hr-text);
  font-family: "Inter", "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
}

/* Smooth scroll for navbar anchor links */
html {
  scroll-behavior: smooth;

  /* LANDING PAGE HR/PROFESSIONAL RESTRUCTURE - STEP 1C FIX 3
     Landing sections already have internal top padding. Keep the browser
     anchor position natural so previous sections do not hang above the
     selected Features, Roles, or Access section. */
  scroll-padding-top: 0;
}

/* =========================================================
   LANDING PAGE HR/PROFESSIONAL RESTRUCTURE - STEP 1C FIX 4
   Exact anchor landing positions.

   HR behaviour:
   - Features / Explore System should land with the Features section
     clearly framed as the main content.
   - Roles should land with the role workspace section clearly framed.
   - Access is intentionally left natural for now because it sits near
     the bottom of the page.
   ========================================================= */

body:not(.dashboard-page) #home,
body:not(.dashboard-page) #access {
  scroll-margin-top: 0;
}

body:not(.dashboard-page) #features {
  scroll-margin-top: 0.5rem;
}

body:not(.dashboard-page) #roles {
  scroll-margin-top: 2rem;
}

/*
  =====================================================================
  NAVBAR
  =====================================================================
*/
.hr-navbar {
  background: rgba(248, 249, 255, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(234, 217, 201, 0.75);
}

.hr-brand-mark {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-weight: 700;
  background: linear-gradient(135deg,
      var(--hr-primary) 0%,
      var(--hr-primary-soft) 100%);
  box-shadow: 0 12px 28px rgba(144, 77, 0, 0.18);
}

.hr-brand-text {
  color: var(--hr-primary-dark);
  font-weight: 700;
  letter-spacing: -0.02em;
}

/*
  =====================================================================
  HERO SECTION
  =====================================================================
*/
.hr-hero-section {
  padding-top: 8rem;
  padding-bottom: 5rem;
  position: relative;
  overflow: hidden;
}

.hr-hero-section::before {
  content: "";
  position: absolute;
  top: -80px;
  right: -80px;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  background: rgba(255, 160, 75, 0.18);
  filter: blur(10px);
}

.hr-hero-badge {
  display: inline-block;
  padding: 0.55rem 1rem;
  border-radius: 999px;
  background: #fff6ec;
  color: var(--hr-primary);
  border: 1px solid #f0d7b8;
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.hr-hero-title {
  font-size: clamp(2.4rem, 5vw, 4.8rem);
  line-height: 1.05;
  font-weight: 800;
  letter-spacing: -0.04em;
}

.hr-hero-title .accent {
  color: var(--hr-primary);
  font-style: italic;
}

.hr-hero-copy {
  color: var(--hr-muted);
  font-size: 1.08rem;
  line-height: 1.8;
  max-width: 620px;
}

/* Right hero panel */
.hr-hero-panel,
.hr-modal-panel {
  background: linear-gradient(145deg, #7a4100 0%, #904d00 45%, #ffa04b 100%);
  color: #ffffff;
  border-radius: 1.5rem;
  position: relative;
  overflow: hidden;
  box-shadow: 0 25px 55px rgba(18, 28, 42, 0.12);
}

.hr-hero-panel {
  min-height: 500px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.hr-hero-panel::before,
.hr-hero-panel::after,
.hr-modal-panel::before,
.hr-modal-panel::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
}

.hr-hero-panel::before,
.hr-modal-panel::before {
  width: 220px;
  height: 220px;
  top: -55px;
  right: -55px;
}

.hr-hero-panel::after,
.hr-modal-panel::after {
  width: 160px;
  height: 160px;
  left: -30px;
  bottom: -35px;
}

.hr-panel-box {
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

/*
  =====================================================================
  BUTTONS
  =====================================================================
*/
.hr-btn-primary {
  background: linear-gradient(135deg,
      var(--hr-primary) 0%,
      var(--hr-primary-soft) 100%);
  color: #ffffff;
  border: none;
  border-radius: 999px;
  padding: 0.95rem 1.6rem;
  font-weight: 600;
  box-shadow: 0 14px 30px rgba(144, 77, 0, 0.16);
}

.hr-btn-primary:hover,
.hr-btn-primary:focus {
  color: #ffffff;
  opacity: 0.96;
}

.hr-btn-secondary {
  background: #ffffff;
  color: var(--hr-primary);
  border: 1px solid var(--hr-border);
  border-radius: 999px;
  padding: 0.95rem 1.6rem;
  font-weight: 600;
}

.hr-btn-secondary:hover,
.hr-btn-secondary:focus {
  color: var(--hr-primary-dark);
}

/*
  =====================================================================
  CARDS
  =====================================================================
*/
.hr-mini-card,
.hr-feature-card,
.hr-role-card,
.hr-access-card {
  background: var(--hr-surface);
  border: 1px solid rgba(234, 217, 201, 0.95);
  border-radius: 1.35rem;
  box-shadow: 0 18px 40px rgba(18, 28, 42, 0.06);
}

.hr-feature-icon {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #fff2e5;
  color: var(--hr-primary);
  font-size: 1.35rem;
}

/*
  =====================================================================
  SECTION TYPOGRAPHY
  =====================================================================
*/
.hr-section-title {
  font-size: clamp(1.9rem, 4vw, 3rem);
  font-weight: 800;
  letter-spacing: -0.03em;
}

.hr-section-copy {
  color: var(--hr-muted);
  max-width: 680px;
  line-height: 1.8;
}

/*
  =====================================================================
  MODAL / SIGN-IN
  =====================================================================
*/
.hr-modal-shell {
  border-radius: 1.5rem;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 24px 55px rgba(18, 28, 42, 0.14);
}

/* Custom input appearance */
.form-control,
.form-select,
.input-group-text {
  min-height: 50px;
  border-color: var(--hr-border);
}

.form-control,
.form-select {
  border-radius: 0.9rem;
}

.input-group>.input-group-text {
  border-radius: 0.9rem 0 0 0.9rem;
}

.input-group>.form-control:last-child,
.input-group>.btn:last-child {
  border-radius: 0 0.9rem 0.9rem 0;
}

.form-control:focus,
.form-select:focus {
  border-color: var(--hr-primary-soft);
  box-shadow: 0 0 0 0.25rem rgba(144, 77, 0, 0.15);
}

.hr-link {
  color: var(--hr-primary);
  font-weight: 600;
  text-decoration: none;
}

.hr-link:hover {
  text-decoration: underline;
}

.hr-dev-note {
  border-left: 4px solid var(--hr-primary-soft);
  background: var(--hr-soft-surface);
  border-radius: 1rem;
}

/*
  =====================================================================
  FOOTER
  =====================================================================
*/
.hr-footer {
  background: #f2f4fb;
  border-top: 1px solid rgba(234, 217, 201, 0.8);
}

/*
  =====================================================================
  RESPONSIVE TUNING
  =====================================================================
*/
@media (max-width: 991.98px) {
  .hr-hero-section {
    padding-top: 7rem;
  }

  .hr-hero-panel {
    min-height: auto;
  }
}

/* =========================================================
   DASHBOARD SHARED STYLES
   These styles give the HR and Employee dashboards a more
   polished product feel while keeping Bootstrap structure.
   ========================================================= */

.dashboard-page {
  background: linear-gradient(180deg, #f7f4ef 0%, #f4f6f9 100%);
  min-height: 100vh;
}

/* =========================================================
   ALPATECH BRANDING - STEP 1C
   Tenant/workspace shell branding for Alpatech.

   HR/product behaviour:
   - Changes visual identity only.
   - Does not change employee, payroll, payslip, CSV export, email,
     Supabase, tenant filtering, or role/access behaviour.
   - Uses the flame icon as an image and renders ALPATECH as CSS text
     so the wordmark remains sharp and professional.
   ========================================================= */

body.alpatech-workspace {
  --hr-primary: #0b5f95;
  --hr-primary-soft: #36b9cf;
  --hr-primary-dark: #08446d;
  --hr-background: #f4f8fb;
  --hr-surface: #ffffff;
  --hr-text: #101828;
  --hr-muted: #667085;
  --hr-border: #d8e5ee;
  --hr-soft-surface: #eef9fc;
  background: linear-gradient(180deg, #f4f8fb 0%, #eef4f8 100%);
}

body.alpatech-workspace .dashboard-hero {
  padding: clamp(1.65rem, 3vw, 2.6rem);
  background:
    radial-gradient(circle at top right, rgba(54, 185, 207, 0.34), transparent 34%),
    linear-gradient(135deg, #073b63 0%, #0b5f95 58%, #37b9cf 100%);
  box-shadow: 0 20px 44px rgba(7, 59, 99, 0.2);
}

body.alpatech-workspace .dashboard-hero::before,
body.alpatech-workspace .dashboard-hero::after {
  background: rgba(255, 255, 255, 0.1);
}

body.alpatech-workspace .hero-badge {
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.22);
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

body.alpatech-workspace .hero-meta-card {
  background: rgba(255, 255, 255, 0.13);
  border-color: rgba(255, 255, 255, 0.2);
}

/* ALPATECH TENANT BRANDING - STEP 1G
   Keep the hero brand calm and breathable.
   The logo, badge, heading, and copy now have deliberate spacing instead
   of being visually packed into one tight cluster. */
.alpatech-hero-content {
  max-width: 760px;
}

.alpatech-hero-kicker-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.85rem;
  margin-bottom: 1.05rem;
}

.alpatech-hero-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  min-height: 50px;
  padding: 0.5rem 0.9rem;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.97);
  border: 1px solid rgba(216, 229, 238, 0.92);
  box-shadow: 0 14px 30px rgba(7, 59, 99, 0.16);
}

.alpatech-hero-badge {
  margin-bottom: 0;
  min-height: 38px;
  padding-inline: 0.8rem;
}

.alpatech-hero-copy {
  max-width: 690px;
  line-height: 1.55;
}

.alpatech-brand-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}

.alpatech-brand-mark img {
  display: block;
  width: 28px;
  height: 38px;
  object-fit: contain;
}

/* ALPATECH LOGO REFINEMENT - STEP 1I
   Add the subtle divider/slash between the flame icon and ALPATECH wordmark.

   HR/product behaviour:
   - Visual branding only.
   - Applies only inside Alpatech workspace shell branding.
   - Does not affect tenant logic, payroll, payslip, leave, email, or access.
   - Keeps non-Alpatech BexHR branding unchanged. */
body.alpatech-workspace .alpatech-hero-brand .alpatech-brand-mark::after {
  content: "";
  display: inline-block;
  width: 1px;
  height: 34px;
  margin-left: 0.55rem;
  background: linear-gradient(
    180deg,
    transparent 0%,
    rgba(148, 163, 184, 0.35) 16%,
    rgba(148, 163, 184, 0.72) 50%,
    rgba(148, 163, 184, 0.35) 84%,
    transparent 100%
  );
  transform: none;
}

/* ALPATECH LOGO REFINEMENT - STEP 1I-FIX 2
   Sidebar uses .bexhr-sidebar-brand::after for the ALPATECH wordmark,
   so the safest sidebar-only divider is a real right border on the flame
   mark itself. This creates: Flame | ALPATECH. */
body.alpatech-workspace .bexhr-sidebar-brand .alpatech-brand-mark {
  padding-right: 0.55rem;
  margin-right: 0.1rem;
  border-right: 1px solid rgba(148, 163, 184, 0.65);
}

/* ALPATECH LOGO REFINEMENT - STEP 1I
   Tighten the wordmark spacing after adding the divider so the logo still
   feels like one composed brand mark rather than three separated items. */
body.alpatech-workspace .alpatech-hero-brand {
  gap: 0.55rem;
}

body.alpatech-workspace .bexhr-sidebar-brand {
  gap: 0.45rem;
}

.alpatech-hero-mark img {
  width: 30px;
  height: 40px;
}

.alpatech-brand-wordmark {
  color: #0b5f95;
  font-size: clamp(1.35rem, 2.5vw, 1.75rem);
  font-weight: 500;
  letter-spacing: 0.14em;
  line-height: 1;
}

/* ALPATECH TENANT BRANDING - STEP 1G
   While the full tenant/company identity is resolving, hide only the
   brand-bearing areas. This prevents a BexHR flash for Alpatech without
   hiding operational cards or blocking the whole dashboard. */
body.alpatech-workspace.alpatech-branding-resolving #tenantSidebarBrand,
body.alpatech-workspace.alpatech-branding-resolving #tenantHeroBrandingBlock {
  opacity: 0;
}

@media (max-width: 575.98px) {
  body.alpatech-workspace .dashboard-hero {
    padding: 1.35rem;
  }

  .alpatech-hero-kicker-row {
    align-items: flex-start;
    gap: 0.7rem;
    margin-bottom: 0.9rem;
  }

  .alpatech-hero-brand,
  .alpatech-hero-badge {
    width: 100%;
    justify-content: flex-start;
  }

  .alpatech-brand-wordmark {
    font-size: 1.25rem;
  }
}

body.alpatech-workspace .dashboard-avatar {
  color: #08446d;
  background: linear-gradient(135deg, #ffffff 0%, #e7f7fb 100%);
  border-color: rgba(255, 255, 255, 0.72);
}

body.alpatech-workspace .btn-primary,
body.alpatech-workspace .dashboard-action-btn.btn-primary {
  background-color: #0b5f95;
  border-color: #0b5f95;
}

body.alpatech-workspace .btn-primary:hover,
body.alpatech-workspace .dashboard-action-btn.btn-primary:hover {
  background-color: #08446d;
  border-color: #08446d;
}

body.alpatech-workspace .btn-outline-primary {
  color: #0b5f95;
  border-color: #0b5f95;
}

body.alpatech-workspace .btn-outline-primary:hover {
  color: #ffffff;
  background-color: #0b5f95;
  border-color: #0b5f95;
}

/* ALPATECH ANNUAL LEAVE BRANDING - STEP 1A
   Tenant-scoped styling for employee leave entitlement cards only.
   Non-Alpatech tenants keep the default BexHR info-tile styling. */
body.alpatech-workspace .leave-entitlement-tile {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(11, 95, 149, 0.18);
  background:
    radial-gradient(circle at top right, rgba(11, 95, 149, 0.12), transparent 34%),
    linear-gradient(180deg, #ffffff 0%, #f7fbfd 100%);
  box-shadow:
    0 14px 34px rgba(11, 95, 149, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

body.alpatech-workspace .leave-entitlement-tile::before {
  content: "";
  position: absolute;
  left: 1rem;
  right: 1rem;
  top: 0;
  height: 4px;
  border-radius: 999px;
  background: linear-gradient(90deg, #0b5f95 0%, #1d9bd7 100%);
  opacity: 0.95;
}

body.alpatech-workspace .leave-entitlement-tile .info-tile-label {
  color: #667085;
  font-weight: 700;
}

body.alpatech-workspace .leave-entitlement-tile .info-tile-value {
  color: #0b3558;
}

body.alpatech-workspace .leave-entitlement-tile .progress {
  background-color: rgba(11, 95, 149, 0.12);
}

@media (min-width: 992px) {
  body.alpatech-workspace .bexhr-sidebar {
    background:
      radial-gradient(circle at top left, rgba(54, 185, 207, 0.16), transparent 34%),
      linear-gradient(180deg, #ffffff 0%, #f3f9fc 100%);
    border-right-color: rgba(216, 229, 238, 0.95);
    box-shadow: 8px 0 28px rgba(7, 59, 99, 0.07);
  }

  body.alpatech-workspace .bexhr-sidebar-brand {
    border-bottom-color: rgba(216, 229, 238, 0.95);
  }

  body.alpatech-workspace .bexhr-sidebar-brand::after {
    content: "ALPATECH";
    color: #0b5f95;
    font-weight: 500;
    letter-spacing: 0.12em;
  }

  body.alpatech-workspace .bexhr-sidebar-brand .alpatech-brand-mark img {
    width: 24px;
    height: 34px;
  }

  body.alpatech-workspace .bexhr-sidebar-item:hover {
    background: #eaf8fb;
    color: #08446d;
  }

  body.alpatech-workspace .bexhr-sidebar-item:hover i {
    color: #0b5f95;
  }

  body.alpatech-workspace .bexhr-sidebar-item.active {
    background: linear-gradient(135deg, #eaf8fb 0%, #f5fbfd 100%);
    color: #08446d;
    box-shadow: inset 0 0 0 1px rgba(11, 95, 149, 0.1);
  }

  body.alpatech-workspace .bexhr-sidebar-item.active::before {
    background: linear-gradient(180deg, #0b5f95 0%, #36b9cf 100%);
  }

  body.alpatech-workspace .bexhr-sidebar-item.active i {
    color: #0b5f95;
  }

  body.alpatech-workspace .bexhr-sidebar-footer {
    border-top-color: rgba(216, 229, 238, 0.95);
  }

  body.alpatech-workspace .bexhr-sidebar-footer .bexhr-sidebar-item:hover {
    background: #eaf8fb;
    color: #08446d;
  }
}

.dashboard-hero {
  background: linear-gradient(135deg, #7a4300 0%, #b96a10 55%, #e7963a 100%);
  color: #ffffff;
  border-radius: 28px;
  padding: 2rem;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.12);
  position: relative;
  overflow: hidden;
}

.dashboard-hero::before,
.dashboard-hero::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
}

.dashboard-hero::before {
  width: 220px;
  height: 220px;
  right: -60px;
  top: -60px;
}

.dashboard-hero::after {
  width: 160px;
  height: 160px;
  left: -40px;
  bottom: -50px;
}

.dashboard-hero>* {
  position: relative;
  z-index: 2;
}

.dashboard-hero::before,
.dashboard-hero::after {
  z-index: 1;
  pointer-events: none;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  background: rgba(255, 255, 255, 0.16);
  color: #fff;
  padding: 0.45rem 0.9rem;
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

.hero-meta-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 1rem;
  margin-top: 1.5rem;
}

.hero-meta-card {
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 20px;
  padding: 1rem 1.1rem;
  backdrop-filter: blur(4px);
}

.hero-meta-label {
  font-size: 0.82rem;
  opacity: 0.9;
  margin-bottom: 0.35rem;
}

.hero-meta-value {
  font-weight: 700;
  word-break: break-word;
}

.dashboard-section-card {
  border: 0;
  border-radius: 24px;
  box-shadow: 0 12px 28px rgba(16, 24, 40, 0.08);
  background: #ffffff;
}

.dashboard-section-card .section-heading {
  font-weight: 800;
  color: #16233b;
}

.dashboard-section-card .section-subtext {
  color: #667085;
}

.info-tile {
  height: 100%;
  border-radius: 22px;
  border: 1px solid #e8edf3;
  background: linear-gradient(180deg, #ffffff 0%, #fbfcfe 100%);
  padding: 1rem 1.1rem;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.info-tile-label {
  font-size: 0.86rem;
  color: #667085;
  margin-bottom: 0.45rem;
}

.info-tile-value {
  font-size: 1.05rem;
  font-weight: 700;
  color: #14213d;
  word-break: break-word;
}

.dashboard-note {
  border-radius: 22px;
  background: linear-gradient(135deg, #fff7ed 0%, #fffbf5 100%);
  border: 1px solid #f5d7b2;
  padding: 1rem 1.1rem;
  color: #8b5e25;
}

.dashboard-table-wrap {
  border: 1px solid #edf1f5;
  border-radius: 20px;
  overflow: hidden;
}

.dashboard-table-wrap .table {
  margin-bottom: 0;
}

.dashboard-table-wrap thead th {
  background: #f8fafc;
  color: #475467;
  font-size: 0.85rem;
  font-weight: 700;
  border-bottom: 1px solid #e9eef5;
}

.dashboard-table-wrap tbody td {
  vertical-align: middle;
}

.dashboard-action-btn {
  border-radius: 14px;
  font-weight: 600;
}

.dashboard-form-card .form-control,
.dashboard-form-card .form-select {
  border-radius: 16px;
  min-height: 50px;
}

.dashboard-form-card .form-control:focus,
.dashboard-form-card .form-select:focus {
  box-shadow: 0 0 0 0.18rem rgba(233, 150, 59, 0.2);
  border-color: #e7963a;
}

.dashboard-form-card .btn {
  border-radius: 16px;
  min-height: 48px;
  font-weight: 700;
}

.dashboard-avatar {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.35rem;
  font-weight: 800;
  color: #7a4300;
