}

.dashboard-header-card {
  background: #ffffff;
  border: 1px solid #e9ecef;
  border-radius: 1rem;
  padding: 1.25rem;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.03);
}

.dashboard-card {
  border: 1px solid #e9ecef;
  border-radius: 1rem;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.03);
}

.profile-avatar-wrapper {
