}

/* Desktop-only tightening so mobile keeps comfortable breathing room. */
@media (min-width: 992px) {
  body:not(.dashboard-page) .hr-hero-title {
    font-size: clamp(3rem, 4.6vw, 4.45rem);
    max-width: 650px;
  }

  body:not(.dashboard-page) .hr-hero-section .row.align-items-center {
    align-items: center !important;
  }

  #features {
    margin-top: -0.75rem;
  }

