/* =========================================================
   BEXHR EMPLOYEE FORM PROGRESS STEPPER
   Informational step indicator for the long employee enrolment
   form. Steps turn amber with a checkmark when the section has
   data (class added by JS via updateEmployeeFormSteps()).
   ========================================================= */

.bexhr-form-steps {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0;
  padding: 0.75rem 1rem;
  background: #fafbfc;
  border: 1px solid #edf1f5;
  border-radius: 16px;
}

.bexhr-form-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
  min-width: 56px;
}

.bexhr-step-dot {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 2px solid #d1d8e0;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: #94a3b8;
  transition: border-color 0.2s ease, background 0.2s ease, color 0.2s ease;
  position: relative;
}

/* Show number by default, hide checkmark */
.bexhr-step-dot .bi-check-lg {
  display: none;
}

.bexhr-step-dot .bexhr-step-num {
  display: block;
}

/* When step is done: amber dot, checkmark visible */
.bexhr-form-step.form-step-done .bexhr-step-dot {
  border-color: var(--hr-primary);
  background: var(--hr-primary);
  color: #ffffff;
}

.bexhr-form-step.form-step-done .bexhr-step-dot .bi-check-lg {
  display: block;
}

.bexhr-form-step.form-step-done .bexhr-step-dot .bexhr-step-num {
  display: none;
}

.bexhr-form-step.form-step-done .bexhr-step-label {
  color: var(--hr-primary);
  font-weight: 600;
}

.bexhr-step-label {
  font-size: 0.72rem;
  color: #94a3b8;
  font-weight: 500;
  white-space: nowrap;
  transition: color 0.2s ease;
}

.bexhr-form-step-connector {
  flex: 1;
  height: 2px;
  background: #e2e8f0;
  min-width: 12px;
  margin-bottom: 1.15rem;
  /* align with dot centre */
  transition: background 0.2s ease;
}

/* Connector goes amber when the step before it is done */
.bexhr-form-step.form-step-done+.bexhr-form-step-connector {
  background: var(--hr-primary-soft);
}

@media (max-width: 575.98px) {
  .bexhr-form-steps {
    gap: 0.25rem;
  }

  .bexhr-step-label {
    display: none;
    /* just show dots on very small screens */
  }

  .bexhr-form-step-connector {
    min-width: 8px;
  }
}

