:root {
  --sidebar-width: 200px;
}

/* Shift page body to make room for the sidebar on large screens */
@media (min-width: 992px) {
  body.bexhr-has-sidebar {
    padding-left: var(--sidebar-width);
  }
}

.bexhr-sidebar {
  display: none;
  /* hidden on mobile */
}

@media (min-width: 992px) {
  .bexhr-sidebar {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: var(--sidebar-width);
    background: #ffffff;
    border-right: 1px solid rgba(234, 217, 201, 0.8);
    box-shadow: 2px 0 16px rgba(18, 28, 42, 0.05);
    z-index: 1040;
    padding: 1.25rem 0.75rem;
    gap: 0.5rem;
  }
}

.bexhr-sidebar-brand {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.25rem 0.5rem 1rem;
  border-bottom: 1px solid rgba(234, 217, 201, 0.6);
  margin-bottom: 0.5rem;
}

.bexhr-sidebar-brand::after {
  content: "BexHR";
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--hr-primary-dark);
  letter-spacing: -0.02em;
}

.bexhr-sidebar-nav {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  flex: 1;
}

.bexhr-sidebar-footer {
  border-top: 1px solid rgba(234, 217, 201, 0.6);
  padding-top: 0.75rem;
}

.bexhr-sidebar-item {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  width: 100%;
  padding: 0.6rem 0.75rem;
  border: none;
  border-radius: 10px;
  background: transparent;
  color: var(--hr-muted);
  font-size: 0.875rem;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  text-align: left;
  transition: background 0.15s ease, color 0.15s ease;
}

.bexhr-sidebar-item.active {
  background: #fff2e5;
  color: var(--hr-primary);
  font-weight: 600;
}

/* Hide the workspace-switcher tab card on desktop when sidebar is present */
@media (min-width: 992px) {
  body.bexhr-has-sidebar .workspace-switcher-card {
    display: none !important;
  }
}

/* =========================================================
   SKELETON LOADING SHIMMER
   Applied to stat tiles and hero meta values while data loads.
   JS removes the class and sets real text once data arrives.
   ========================================================= */

@keyframes skeletonShimmer {
  0% {
    background-position: -400px 0;
  }

  100% {
    background-position: 400px 0;
  }
}

.skeleton {
  display: inline-block;
  min-width: 48px;
  min-height: 1em;
  border-radius: 6px;
  background: linear-gradient(90deg,
      #e8edf3 25%,
      #f4f6f9 50%,
      #e8edf3 75%);
  background-size: 800px 100%;
  animation: skeletonShimmer 1.4s ease-in-out infinite;
  color: transparent !important;
  user-select: none;
  vertical-align: middle;
}

/* Wider skeleton for text values like email */
.skeleton-wide {
  min-width: 120px;
}

