/* =========================================================
   EMPLOYEE UI CLEANUP - STEP 1I
   Floating Back-to-Top arrow button.
   ========================================================= */

.dashboard-scroll-top-btn {
  position: fixed;
  right: 1.25rem;
  bottom: 1.25rem;
  z-index: 1080;
  width: 44px;
  height: 44px;
  border: 1px solid var(--hr-primary);
  border-radius: 999px;
  background-color: var(--hr-primary);
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 14px 30px rgba(144, 77, 0, 0.28);
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    background-color 0.18s ease,
    border-color 0.18s ease;
}

.dashboard-scroll-top-btn:hover,
.dashboard-scroll-top-btn:focus {
  border-color: var(--hr-primary-dark);
  background-color: var(--hr-primary-dark);
  color: #ffffff;
  transform: translateY(-2px);
  box-shadow: 0 18px 36px rgba(144, 77, 0, 0.36);
}

.dashboard-scroll-top-btn i {
  font-size: 1.15rem;
  line-height: 1;
}

@media (max-width: 575.98px) {
  .dashboard-scroll-top-btn {
    right: 0.9rem;
    bottom: 0.9rem;
    width: 42px;
    height: 42px;
  }
}

/* =========================================================
   EMPLOYEE UI CLEANUP - STEP 1J
   Read-only Employee Profile field styling.
   ========================================================= */

#profileSection input.form-control[readonly] {
  background-color: #f1f3f5;
  border-color: #d9dee7;
  color: #6c757d;
  cursor: not-allowed;
  box-shadow: none;
  opacity: 1;
}

#profileSection input.form-control[readonly]:focus {
  background-color: #f1f3f5;
  border-color: #d9dee7;
  color: #6c757d;
  box-shadow: none;
}

#profileSection input.form-control[readonly]::placeholder {
  color: #9aa3af;
}

/* =========================================================
   EMPLOYEE UI CLEANUP - STEP 1J
   Profile image upload empty-state button.
   ========================================================= */

#profileSection #saveProfileImageBtn:disabled,
#profileSection #saveProfileImageBtn.profile-upload-empty {
  background-color: #adb5bd;
  border-color: #adb5bd;
  color: #ffffff;
  opacity: 1;
  cursor: not-allowed;
  box-shadow: none;
}

#profileSection #saveProfileImageBtn:disabled:hover,
#profileSection #saveProfileImageBtn:disabled:focus,
#profileSection #saveProfileImageBtn.profile-upload-empty:hover,
#profileSection #saveProfileImageBtn.profile-upload-empty:focus {
  background-color: #adb5bd;
  border-color: #adb5bd;
  color: #ffffff;
  transform: none;
  box-shadow: none;
}

#profileSection #saveProfileImageBtn:not(:disabled):not(.profile-upload-empty) {
  cursor: pointer;
}

/* =========================================================
   CROSS-DASHBOARD UI CLEANUP - STEP 1A
   Global brown Back-to-Top controls + HR Payslip Email Status scroll.

   Purpose:
   - Make all floating up-arrow buttons use the BexHR brown brand colour.
   - Avoid page stretching when HR Payslip Email Status has many records.
   - CSS-only where possible so Admin/HR/Manager/Employee JS stays untouched.
   ========================================================= */

/* HR Payslip Email Status inner scroll. */
#payslipEmailLogsTableWrapper {
  max-height: 320px;
  overflow-y: auto !important;
  overflow-x: auto !important;
  overscroll-behavior: contain;
  border-radius: 20px;
}

/* Keep the HR payslip email table readable inside the inner scroll area. */
#payslipEmailLogsTableWrapper table {
  min-width: 860px;
}

/* =========================================================
   CROSS-DASHBOARD UI CLEANUP - STEP 1A-2
   Respect hidden state + lighter Back-to-Top arrow.

   Purpose:
   - Keep the button hidden while the dashboard is near the top.
   - Show it only when JS removes d-none after scrolling.
   - Use a lighter native arrow glyph so the control looks professional.
   - CSS-only; no dashboard JS changes.
   ========================================================= */

/* Keep Bootstrap/JS hiding behaviour authoritative. */
body.dashboard-page #backToTopBtn.d-none,
body.dashboard-page #scrollToTopBtn.d-none,
body.dashboard-page .bexhr-back-to-top-btn.d-none,
body.dashboard-page .dashboard-scroll-top-btn.d-none {
  display: none !important;
}

/* Style the floating button only when it is actually visible. */
body.dashboard-page #backToTopBtn:not(.d-none),
body.dashboard-page #scrollToTopBtn:not(.d-none),
body.dashboard-page .bexhr-back-to-top-btn:not(.d-none),
body.dashboard-page .dashboard-scroll-top-btn:not(.d-none) {
  position: fixed !important;
  right: 1.5rem !important;
  bottom: 1.5rem !important;
  z-index: 1080 !important;
  width: 44px !important;
  height: 44px !important;
  min-width: 44px !important;
  min-height: 44px !important;
  padding: 0 !important;
  border-radius: 999px !important;
  background-color: var(--hr-primary) !important;
  border: 1px solid var(--hr-primary) !important;
  color: #ffffff !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  line-height: 1 !important;
  font-size: 0 !important;
  box-shadow: 0 14px 30px rgba(144, 77, 0, 0.28) !important;
}

/* Hide the icon-font version only while the CSS glyph is used. */
body.dashboard-page #backToTopBtn:not(.d-none)>i,
body.dashboard-page #scrollToTopBtn:not(.d-none)>i,
body.dashboard-page .bexhr-back-to-top-btn:not(.d-none)>i,
body.dashboard-page .dashboard-scroll-top-btn:not(.d-none)>i {
  display: none !important;
}

/* Lighter native arrow glyph. */
body.dashboard-page #backToTopBtn:not(.d-none)::before,
body.dashboard-page #scrollToTopBtn:not(.d-none)::before,
