/* =========================================================
   PAYSLIP DOCUMENT SYSTEM - PREVIEW + SELF-SERVICE
   Shared visual language for HR Payroll and Self-Service payslips.
   Presentation only: payroll calculations, authorised-record queries,
   tenant filtering, email delivery, and access controls are unchanged.
   ========================================================= */

.bexhr-payslip-modal {
  padding: 0;
  background: rgba(15, 23, 42, 0.62) !important;
  backdrop-filter: blur(8px);
}

.bexhr-payslip-modal-container {
  max-width: 1080px;
}

.bexhr-payslip-modal-shell {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 980px;
  max-height: 94vh;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.7) !important;
  background: #eef3f7;
  box-shadow: 0 34px 100px rgba(15, 23, 42, 0.36) !important;
}

.bexhr-payslip-modal-header,
.bexhr-payslip-modal-footer {
  flex: 0 0 auto;
  background: #ffffff !important;
}

.bexhr-payslip-modal-header {
  border-bottom: 1px solid #e2e8f0 !important;
  background:
    radial-gradient(circle at top right, rgba(14, 165, 164, 0.12), transparent 34%),
    #ffffff !important;
}

.bexhr-payslip-modal-header h2 {
  color: #10233f;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.bexhr-payslip-modal-content {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  background: #eef3f7;
  scrollbar-width: thin;
}

.bexhr-payslip-modal-content::-webkit-scrollbar {
  width: 10px;
}

.bexhr-payslip-modal-content::-webkit-scrollbar-thumb {
  border: 2px solid #eef3f7;
  border-radius: 999px;
  background: rgba(15, 35, 63, 0.25);
}

.bexhr-payslip-modal-footer {
  border-top: 1px solid #e2e8f0 !important;
}

.bexhr-payslip-document {
  display: grid;
  gap: 1rem;
  width: 100%;
  max-width: 860px;
  margin: 0 auto;
  padding: clamp(1rem, 2.6vw, 1.65rem);
  border: 1px solid #d9e3ec;
  border-radius: 24px;
  background: #ffffff;
  box-shadow: 0 20px 52px rgba(15, 23, 42, 0.1);
}

.bexhr-payslip-letterhead {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1.25rem;
  padding: 1.15rem 1.25rem;
  overflow: hidden;
  border-radius: 18px;
  color: #ffffff;
  background:
